// DLD Transaction Cost Breakdown (AED)
function calculateDLDTransferCost(propertyPriceAED) {
  const dldFee = propertyPriceAED * 0.04; // 4% DLD transfer fee
  const adminFee = 580; // DLD admin fee
  const trusteeFee = propertyPriceAED >= 500000 ? 4000 : 2000; // Registration Trustee fee
  const trusteeVat = trusteeFee * 0.05;
  return {
    dldFee,
    trusteeFee: trusteeFee + trusteeVat,
    totalGovCosts: dldFee + adminFee + trusteeFee + trusteeVat
  };
}

