// RERA Rent Increase Matrix (Law 43 of 2013)
function getReraAllowedIncrease(currentRent, benchmarkMarketRent) {
  const pctBelow = ((benchmarkMarketRent - currentRent) / benchmarkMarketRent) * 100;
  if (pctBelow <= 10) return 0;       // Up to 10% below: 0% increase
  if (pctBelow <= 20) return 0.05;    // 11-20% below: max 5% increase
  if (pctBelow <= 30) return 0.10;    // 21-30% below: max 10% increase
  if (pctBelow <= 40) return 0.15;    // 31-40% below: max 15% increase
  return 0.20;                        // > 40% below: max 20% increase
}
